<div class="page-head"><div><h1>Edit Campaign</h1><p>Update campaign plan and generated sales.</p></div><a class="btn btn-light border" href="<?=e(url('marketing/index.php'))?>">Back</a></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="card-panel"><div class="card-body"><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Campaign Name</label><input class="form-control" name="campaign_name" value="<?=e($_POST['campaign_name']??$c['campaign_name'])?>"></div><div class="col-md-3"><label class="form-label">Type</label><input class="form-control" name="campaign_type" value="<?=e($_POST['campaign_type']??$c['campaign_type'])?>"></div><div class="col-md-3"><label class="form-label">Department</label><select class="form-select" name="department_id"><?php foreach(departments() as $d):?><option value="<?=$d['id']?>" <?=((int)($_POST['department_id']??$c['department_id'])===(int)$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Start</label><input class="form-control" type="date" name="start_date" value="<?=e($_POST['start_date']??$c['start_date'])?>"></div><div class="col-md-3"><label class="form-label">End</label><input class="form-control" type="date" name="end_date" value="<?=e($_POST['end_date']??$c['end_date'])?>"></div><div class="col-md-3"><label class="form-label">Budget</label><input class="form-control" type="number" step=".01" name="budget" value="<?=e($_POST['budget']??$c['budget'])?>"></div><div class="col-md-3"><label class="form-label">Generated Sales</label><input class="form-control" type="number" step=".01" name="generated_sales" value="<?=e($_POST['generated_sales']??$c['generated_sales'])?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['Planned','Active','Completed','Cancelled'] as $st):?><option <?=($_POST['status']??$c['status'])===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-primary">Save Changes</button></div></div></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
